<?php
namespace App\Http\Controllers;
use App\Models\{Apprentice,User,Programme,TutorGroup,ApprenticeSetupCase as SetupCase};
use App\Support\{CohortSetup as Setup,LearningAccess};
use Illuminate\Http\Request;
use Illuminate\Pagination\LengthAwarePaginator;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\Rule;
class CohortSetupController extends Controller {
 private function manager(Request $r):void {abort_unless(LearningAccess::manager($r->user()),403);}
 private function view(string $v,array $d=[]) {return response()->view('intakes.'.$v,$d)->header('Cache-Control','no-store, private')->header('Referrer-Policy','no-referrer');}
 private function filters(Request $r):array {return $r->validate(['search'=>['nullable','string','max:100'],'programme_id'=>['nullable','integer','min:1'],'tutor_group_id'=>['nullable','integer','min:1'],'start_from'=>['nullable','date_format:Y-m-d'],'start_to'=>['nullable','date_format:Y-m-d','after_or_equal:start_from'],'issue'=>['nullable',Rule::in(['all',...array_keys(Setup::ISSUES)])],'page'=>['nullable','integer','min:1']]);}
 public function readiness(Request $r) {$this->manager($r);$filters=$this->filters($r);$result=Setup::selected($filters);$page=(int)$r->input('page',1);$rows=new LengthAwarePaginator(array_slice($result['rows'],($page-1)*25,25),count($result['rows']),25,$page,['path'=>$r->url(),'query'=>$r->except('page')]);return $this->view('readiness',['rows'=>$rows,'result'=>$result,'filters'=>$filters,'programmes'=>Programme::orderBy('name')->get(['id','name','standard_code','version']),'groups'=>TutorGroup::orderBy('name')->get(['id','name'])]);}
 public function export(Request $r) {$this->manager($r);$result=Setup::selected($this->filters($r));return response()->json(['matched_profiles'=>$result['matched_profiles'],'counts'=>$result['counts'],'rows'=>array_map(fn($row)=>['id'=>$row['apprentice']->id,'reference'=>$row['apprentice']->reference,'issues'=>$row['position']['issues'],'task_count'=>$row['position']['task_count']],$result['rows']),'private_names_emails_notes_exported'=>false,'formal_induction_or_eligibility_approved'=>false],200,['Content-Disposition'=>'attachment; filename="GTA-Cohort-Setup.json"','Cache-Control'=>'no-store, private','Referrer-Policy'=>'no-referrer']);}
 private function data(Request $r,bool $create):array {return $r->validate(['version'=>['required','integer','min:0'],'source_hash'=>['required','regex:/^[a-f0-9]{64}$/D'],'issue'=>[$create?'required':'nullable',Rule::in(array_keys(Setup::ISSUES))],'owner_id'=>['required','integer','min:1'],'due_on'=>['required','date_format:Y-m-d','after_or_equal:today'],'note'=>['required','string','max:2000'],'confirmed'=>['accepted']]);}
 public function create(Request $r,Apprentice $apprentice) {$this->manager($r);$d=$this->data($r,true);$c=Setup::save($r->user(),(int)$r->session()->get('auth_version'),$apprentice,null,(int)$d['version'],$d['source_hash'],$d);return to_route('setup-cases.show',$c)->with('status','Setup follow-up recorded. Underlying setup flags and learner records were not changed.');}
 public function show(Request $r,SetupCase $setupCase) {$this->manager($r);abort_unless(Setup::intact($setupCase),409);$a=Apprentice::findOrFail($setupCase->apprentice_id);$check=Setup::check($a);return $this->view('case',['case'=>$setupCase,'apprentice'=>$a,'check'=>$check,'details'=>$setupCase->details,'position'=>Setup::position($setupCase,$a,$check),'owners'=>User::where('active',true)->whereIn('role',['admin','ceo'])->get(['id','name']),'events'=>DB::table('apprentice_setup_case_events')->where('case_id',$setupCase->id)->orderBy('id')->get(['event','actor_id','created_at'])]);}
 public function save(Request $r,SetupCase $setupCase) {$this->manager($r);$d=$this->data($r,false);Setup::save($r->user(),(int)$r->session()->get('auth_version'),Apprentice::findOrFail($setupCase->apprentice_id),$setupCase,(int)$d['version'],$d['source_hash'],$d);return back()->with('status','Case saved/reopened against the current checked source; earlier decision proof retained in history.');}
 public function decide(Request $r,SetupCase $setupCase) {$this->manager($r);$d=$r->validate(['version'=>['required','integer','min:1'],'source_hash'=>['required','regex:/^[a-f0-9]{64}$/D'],'decision'=>['required','in:resolve,defer,reopen,withdraw'],'note'=>['required','string','max:2000'],'confirmed'=>['accepted']]);Setup::decide($r->user(),(int)$r->session()->get('auth_version'),$setupCase,(int)$d['version'],$d['source_hash'],$d['decision'],$d['note']);return back()->with('status','Follow-up decision recorded. Automatic setup flags remain independent; deferral/withdrawal never make a flag pass.');}
 public function queue(Request $r) {$this->manager($r);$d=$r->validate(['owner'=>['nullable','integer','min:1'],'state'=>['nullable','in:all,Open,Resolved,Deferred,Withdrawn'],'overdue'=>['nullable','boolean'],'page'=>['nullable','integer','min:1']]);$q=SetupCase::query()->when($d['owner']??null,fn($q,$id)=>$q->where('owner_id',$id))->when(($d['state']??'all')!=='all',fn($q)=>$q->where('state',$d['state']));if($r->boolean('overdue')){$q->where('due_on','<',today());}$cases=$q->orderBy('due_on')->orderBy('id')->paginate(25)->withQueryString();$positions=[];$profiles=[];foreach($cases as$c){$a=Apprentice::find($c->apprentice_id);$profiles[$c->id]=$a?['reference'=>$a->reference,'name'=>trim($a->first_name.' '.$a->last_name)]:null;$positions[$c->id]=$a?Setup::position($c,$a):['label'=>'Profile unavailable','overdue'=>true];}$owners=User::whereIn('role',['admin','ceo'])->orderBy('name')->get(['id','name','active']);return $this->view('case-queue',compact('cases','positions','profiles','owners','d'));}
}
